from pathlib import Path
import hashlib,json,re,subprocess,time,datetime
out=Path('reviews/evidence/M1-C1.3-r2')
def read(p):
 b=p.read_bytes();return b.decode('utf-16') if b.startswith(b'\xff\xfe') else b.decode('utf-8-sig')
def counts(name):
 c=[tuple(map(int,x)) for x in re.findall(r'test result:.*? (\d+) passed; (\d+) failed; (\d+) ignored',read(out/name))];return dict(zip(['passed','failed','ignored'],[sum(x[i] for x in c) for i in range(3)]))
def git(*args):return subprocess.check_output(['git',*args],encoding='utf-8').strip()
assert git('rev-parse','HEAD')=='7a5f866794578a9c6de856e852dc719ae16a5dcf'
assert not git('diff','--','spec','crates/executor/src','crates/persist/src','Cargo.lock','deny.toml','desktop/src/ipc/generated')
report=Path('reviews/M1-C1.3-r2.md')
receipt={'reviewedCommit':git('rev-parse','HEAD'),'branch':git('branch','--show-current'),'recordedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'verdict':'block','openFindings':{'P0':0,'P1':4,'P2':2},'round1Closure':{'closed':14,'partiallyClosed':4,'notClosed':0},'registerCounts':json.loads((out/'register-counts.json').read_text()),'rustCounts':{n:counts(n) for n in ['workspace-baseline.log','workspace-final.log','variants.log','format-final.log','format-variants.log','journal.log','diagnostics.log']},'workspaceFinal':json.loads((out/'workspace-final-status.json').read_text()),'newTests':{'total':21,'passed':12,'failed':9,'ignored':0},'fixtureReplacement':{'test':'c13_r1_format::partial_folder_rollback_restores_every_already_replaced_entry','authorization':'Binding orchestrator ruling in round-2 task','cases':12,'passed':12},'commands':{'baseline':'cargo test --workspace --locked (compiled before fixture edit/new tests)','final':'cargo test --workspace --locked --no-fail-fast (compiled before the last manifest-order test was added)','finalFormat':'cargo test -p tt-persist --test c13_r2_format --locked','variants':'cargo test -p tt-executor --test c13_r2_persistence --locked','frontend':'pnpm test','python':'python scripts/run-reviewer-python-suites.py','generated':'cargo test -p tt-engine --test frontend_schemas --locked'},'notes':['Evidence text is decoded to UTF-8/LF from Windows redirection encoding; scoped .gitattributes disables newline conversion so recorded evidence SHA-256 values survive checkout. Raw log whitespace is retained.','Baseline PowerShell wrapper status 1 with native-stderr error records; all test summaries pass. Actual cargo exit recorded separately for final sweep.','Final workspace includes 20 then-present new tests (599/8/2); separate final format target includes the 21st test (5/2/0). Current new-suite total is 12 pass / 9 fail.','The only original reviewer test edit is the ruled v2 fixture replacement; no product/spec edits.'],'timing':{'baselineObservedSpanBeforeLogEncodingNormalizationSeconds':727.0862307548523,'baselineStartToReceiptSeconds':time.time()-(out/'workspace-baseline.log').stat().st_ctime,'budgetSeconds':2700,'scope':'Filesystem spans approximate; exact final cargo duration is monotonic in workspaceFinal. Initial install/read precedes baseline by a few minutes. CI check job durations independently recorded in ci-reviewer-suites.json.'},'sha256':{str(p.relative_to(out)).replace('\\','/'):hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(out.rglob('*')) if p.is_file() and p.name!='review-receipt.json'},'reportCanonicalLFSha256':hashlib.sha256(report.read_bytes().replace(b'\r\n',b'\n')).hexdigest()}
(out/'review-receipt.json').write_text(json.dumps(receipt,indent=2,ensure_ascii=False)+'\n',encoding='utf-8');print(json.dumps({'counts':receipt['rustCounts'],'timing':receipt['timing']},indent=2))
